BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='20s';
SELECT jsonb_build_object(
 'captured_at',clock_timestamp(),'read_only',current_setting('transaction_read_only'),'database',current_database(),'current_user',current_user,'session_user',session_user,
 'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition_md5',md5(pg_get_functiondef(p.oid)),'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),'source_md5',md5(p.prosrc),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'acl',p.proacl::text,'public_execute',EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE'),'effective_grants',(SELECT jsonb_object_agg(r.role_name,has_function_privilege(r.role_name,p.oid,'EXECUTE')) FROM (VALUES('anon'),('authenticated'),('service_role')) r(role_name))) ORDER BY p.oid::regprocedure::text COLLATE "C") FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind='f' AND (n.nspname='ytrace_storage_private' OR (n.nspname='public' AND p.proname='admin_authorize_storage_operation'))),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,'name',t.tgname,'enabled',t.tgenabled,'function',fn.nspname||'.'||p.proname||'()','type',t.tgtype,'columns',t.tgattr::text,'definition',pg_get_triggerdef(t.oid,true),'definition_sha256',encode(sha256(convert_to(pg_get_triggerdef(t.oid,true),'UTF8')),'hex')) ORDER BY t.tgname COLLATE "C") FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace fn ON fn.oid=p.pronamespace WHERE NOT t.tgisinternal AND t.tgname IN ('ytrace_remember_template_asset','ytrace_remember_news_asset','ytrace_budget_cleanup','ytrace_liquidation_cleanup','ytrace_ypop_cleanup','ytrace_event_cleanup','ytrace_activity_cleanup','ytrace_move_cleanup')),
 'tables',(SELECT jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text,'public_dml',EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee=0 AND a.privilege_type IN ('SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER')),'effective_grants',(SELECT jsonb_object_agg(r.role_name,jsonb_build_object('select',has_table_privilege(r.role_name,c.oid,'SELECT'),'insert',has_table_privilege(r.role_name,c.oid,'INSERT'),'update',has_table_privilege(r.role_name,c.oid,'UPDATE'),'delete',has_table_privilege(r.role_name,c.oid,'DELETE'),'truncate',has_table_privilege(r.role_name,c.oid,'TRUNCATE'),'references',has_table_privilege(r.role_name,c.oid,'REFERENCES'),'trigger',has_table_privilege(r.role_name,c.oid,'TRIGGER'))) FROM (VALUES('anon'),('authenticated'),('service_role')) r(role_name)),'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(jsonb_build_object('name',con.conname,'definition',pg_get_constraintdef(con.oid)) ORDER BY con.conname COLLATE "C") FROM pg_constraint con WHERE con.conrelid=c.oid)) ORDER BY c.relname COLLATE "C") FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ytrace_storage_private' AND c.relkind='r'),
 'internal_counts',jsonb_build_object('admin_asset_uploads',(SELECT count(*) FROM ytrace_storage_private.admin_asset_uploads),'asset_bindings',(SELECT count(*) FROM ytrace_storage_private.asset_bindings),'trusted_storage_origins',(SELECT count(*) FROM ytrace_storage_private.trusted_storage_origins),'cleanup_receipts',(SELECT count(*) FROM ytrace_storage_private.cleanup_receipts)),
 'schema_acl',(SELECT nspacl::text FROM pg_namespace WHERE nspname='ytrace_storage_private'),
 'trusted_origins',(SELECT array_agg(origin ORDER BY origin COLLATE "C") FROM ytrace_storage_private.trusted_storage_origins),
 'asset_audit',(SELECT jsonb_agg(to_jsonb(a) ORDER BY resource_kind,form,published,resolvable) FROM ytrace_storage_private.asset_reference_audit() a),
 'binding_counts',(SELECT jsonb_object_agg(bucket_id,total) FROM (SELECT bucket_id,count(*) total FROM ytrace_storage_private.asset_bindings GROUP BY bucket_id) a),
 'current_template_resolution',(SELECT jsonb_build_object('total',count(*),'active',count(*) FILTER(WHERE is_active),'resolved',count(*) FILTER(WHERE ytrace_storage_private.public_asset_reference('template-files',template_url) IS NOT NULL),'objects_exist',count(*) FILTER(WHERE EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='template-files' AND o.name=ytrace_storage_private.public_asset_reference('template-files',template_url)))) FROM public.required_document_types),
 'published_news_resolution',(SELECT jsonb_build_object('total',count(*),'published',count(*) FILTER(WHERE visibility_status::text='published'),'resolved',count(*) FILTER(WHERE visibility_status::text='published' AND ytrace_storage_private.public_asset_reference('news-release-images',preview_image_url) IS NOT NULL),'objects_exist',count(*) FILTER(WHERE visibility_status::text='published' AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='news-release-images' AND o.name=ytrace_storage_private.public_asset_reference('news-release-images',preview_image_url)))) FROM public.news_releases),
 'environment_guard',public.is_development_or_test_environment(),
 'storage_policy_count',(SELECT count(*) FROM pg_policies WHERE schemaname='storage' AND tablename='objects')
) AS foundation_verification;
ROLLBACK;
